interface.definition:
#"SYSTEM_SYSRULES_gridField_v1"(
  label: "Core ASKs",
  labelPosition: "COLLAPSED",
  emptyGridMessage: "No Core ASKs Found",
  data: ri!coreAsks,
  refreshAlways: true,
  columns: {
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Request Number",
      sortField: "askId",
      value: #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: index(
            split(fv!row.dppGroup, "–"),
            1,
            tointeger(null)
          ) & " - " & "FY" & right(fv!row.fyear, 2),
          link: #"SYSTEM_SYSRULES_recordLink"(
            recordType: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3310219",
            identifier: fv!row.askDetailId
          )
        )
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Name of the ASK",
      sortField: "coreAskName",
      value: fv!row.coreAskName
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "DPP Group",
      sortField: "dppGroup",
      value: fv!row.dppGroup
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Level",
      sortField: "levelNeed",
      value: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.levelNeed),
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
        fv!row.levelNeed
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Outgoing Resource",
      sortField: "outGoingResource",
      value: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.outGoingResource),
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
        fv!row.outGoingResource
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Reason",
      sortField: "needReason",
      value: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.needReason),
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
        fv!row.needReason
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Year",
      sortField: "fYear",
      value: fv!row.fYear
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Projected Start Date",
      sortField: "projectedStartDate",
      value: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.projectedStartDate),
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
        fv!row.projectedStartDate
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Retirement/ End Date",
      sortField: "endDate",
      value: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.endDate),
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
        fv!row.endDate
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "General/ Specialty",
      sortField: "generalSpecialityNeed",
      value: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.generalSpecialityNeed),
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
        fv!row.generalSpecialityNeed
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Role Posting",
      sortField: "rolePosting",
      value: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(fv!row.rolePosting),
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
        fv!row.rolePosting
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Version",
      sortField: "version",
      value: #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: #"SYSTEM_SYSRULES_richTextItem_v1"(text: fv!row.version)
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: "Status",
      sortField: "isCompleted",
      value: #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: #"SYSTEM_SYSRULES_richTextIcon"(
          icon: if(
            fv!row.isCompleted,
            "check-circle-o",
            fv!row.statusId = #"_a-0000ef82-c68c-8000-9c6c-011c48011c48_14274552",
            "times-circle-o",
            "play-circle-o"
          ),
          size: "MEDIUM",
          color: if(
            fv!row.isCompleted,
            "POSITIVE",
            fv!row.statusId = #"_a-0000ef82-c68c-8000-9c6c-011c48011c48_14274552",
            "NEGATIVE",
            "#F1CE0B"
          ),
          caption: if(
            fv!row.isCompleted,
            "Completed",
            fv!row.statusId = #"_a-0000ef82-c68c-8000-9c6c-011c48011c48_14274552",
            "Cancelled",
            "In Progress"
          )
        )
      )
    ),
    /*a!gridColumn(*/
    /*label: "Status",*/
    /*sortField: "isCompleted",*/
    /*value: a!richTextDisplayField(*/
    /*value: a!richTextIcon(*/
    /*icon: if(*/
    /*fv!row.isCancelled,*/
    /*"times-circle-o",*/
    /*if(*/
    /*fv!row.isCompleted,*/
    /*"check-circle-o",*/
    /*"play-circle-o"*/
    /*)*/
    /*),*/
    /*size: "MEDIUM",*/
    /*color: if(*/
    /*fv!row.isCancelled,*/
    /*"NEGATIVE",*/
    /*if(*/
    /*fv!row.isCompleted,*/
    /*"POSITIVE",*/
    /*"#F1CE0B"*/
    /*)*/
    /*),*/
    /*caption: if(*/
    /*fv!row.isCancelled,*/
    /*"Cancelled",*/
    /*if(*/
    /*fv!row.isCompleted,*/
    /*"Completed",*/
    /*"In Progress"*/
    /*)*/
    /*)*/
    /*)*/
    /*)*/
    /*)*/

  },
  selectionValue: ri!selectedTaskIds,
  selectionSaveInto: ri!selectedTaskIds,
  rowHeader: 1,
  spacing: "DENSE",
  borderStyle: "LIGHT",
  shadeAlternateRows: true(),
  initialSorts: #"SYSTEM_SYSRULES_sortInfo"(field: "askId", ascending: false)
)
